// Pagination helpers
export const createPaginatedResponse = <T>(data: T[], page = 1, perPage = 30) => {
  const start = (page - 1) * perPage;
  const end = start + perPage;
  const items = data.slice(start, end);
  
  const hasNext = end < data.length;
  const hasPrev = page > 1;
  
  const links: string[] = [];
  if (hasNext) {
    links.push(`<https://api.github.com/repos/testuser/test-repo?page=${page + 1}&per_page=${perPage}>; rel="next"`);
  }
  if (hasPrev) {
    links.push(`<https://api.github.com/repos/testuser/test-repo?page=${page - 1}&per_page=${perPage}>; rel="prev"`);
  }
  
  return {
    data: items,
    headers: {
      link: links.length > 0 ? links.join(', ') : undefined,
    },
  };
};